public class ResourceContentionDemo {
    private final Object lockA = new Object();
    private final Object lockB = new Object();

    // Classic Deadlock Scenario
    public void unsafeMethod1() {
        synchronized (lockA) {
            synchronized (lockB) {
                // Critical section
            }
        }
    }

    public void unsafeMethod2() {
        // Reversed acquisition order creates circular wait potential
        synchronized (lockB) {
            synchronized (lockA) {
                // Critical section
            }
        }
    }
}
